const VOICE={"crPrep": ["高速モードの許可を申請します。……許可しました。私が。", "Requesting permission for boost mode. Permission granted. By me."], "mk1": ["マーカーを設置。そこに停めたことは、見なかったことにします。", "Marker placed. I'll pretend I didn't see you park there."], "mk2": ["マーカーを一括削除。まっさらな地図、まっさらな一日です。", "All markers cleared. A fresh map, and a fresh start."], "map": ["マップを更新。道路は動いていません。二回確認しました。", "Map updated. The roads haven't moved. I checked twice."], "off": ["オフライン準備完了。電波はもう、あってもなくても構いません。", "Offline pack complete. Signal is now optional."], "traf": ["交通解析完了。りんくうが、また大げさに混んでいます。", "Traffic analysis complete. Rinku is being dramatic again."], "flt": ["フライト情報を更新。飛行機は定刻です。誰かさんと違って。", "Flight intel updated. The plane is on time. Unlike some of us."], "list": ["ミッションリストを更新。今日は忙しくなりそうです、エージェント。", "Mission list updated. Today looks busy, Agent."], "obj": ["目標達成。ゲストは無事にお届け、威厳も無傷です。", "Objective complete. Guests delivered, dignity intact."], "area": ["作戦領域に進入。自然にふるまってください。", "Entering mission area. Please act natural."], "leave": ["警告：作戦領域を離脱。景色の良い寄り道なら、別ですが。", "Caution: leaving mission area. Unless this is a scenic detour."], "rtb": ["帰投します。Crane Nest は明かりをつけて待っています。", "Returning to base. Crane Nest has kept the lights on."], "pick": ["お迎えを要請。ゲストの到着時刻をロックしました。", "Pickup requested. Guest ETA locked in."], "land": ["ゲストが着陸。荷物の待ち時間：たぶん、思っているより長め。", "Guest has landed. Estimated baggage wait: longer than you'd like."], "hover": ["お迎え地点で待機中。エンジンは静か、エージェントはもっと静か。", "Standing by at the pickup point. Engine calm, agent calmer."], "bags": ["荷物の数を確認。トランクは覚悟を決めました。", "Luggage count confirmed. The trunk has accepted its fate."], "rain": ["雨が接近中。天気を変えたいところですが、予算がありません。", "Rain approaching. I'd adjust the weather, but I lack the budget."], "clear": ["天候回復。どういたしまして。私ではありませんが、どういたしまして。", "Clouds clearing. You're welcome. That wasn't me, but you're welcome."], "pass": ["パスポート登録を確認。旅人がまた一人、正式に仲間入りです。", "Passport registered. Another traveler, officially accounted for."], "ready": ["お部屋の準備完了。枕にはブリーフィング済みです。", "Room preparation complete. The pillows have been briefed."], "code": ["入口の暗証番号を更新。手のひらに書かないでくださいね。", "Entrance code updated. Please don't write it on your hand."], "late": ["警告：ゲストが遅れています。忍耐と、おやつを推奨。", "Warning: guest running late. Recommend patience, and snacks."], "tape": ["新しいテープを入手。作戦のサウンドトラックに追加します。", "New cassette tape acquired. Adding it to the mission soundtrack."], "lrc": ["歌詞を同期。一緒に歌うことが、技術的に可能になりました。", "Lyrics synchronized. Singing along is now technically supported."], "log": ["ログを更新。本日の記録、なかなか立派です。", "Log updated. Today's record looks respectable."], "spd80": ["時速80。制限ちょうど。几帳面ですね、エージェント。", "Eighty. Right at the limit. Very precise, Agent."], "spd100": ["時速100。これ以上は、報告書に書くことになります。", "One hundred. Any faster, and this goes in the report."], "spd120": ["時速120。記録しました。公式には、何も見ていません。", "One twenty. Logged. Officially, I saw nothing."], "spd140": ["時速140。空港は逃げませんよ、Kaku。", "One forty. The airport isn't going anywhere, Kaku."], "cp1": ["チェックポイント1、りんくう。予定どおり通過。", "Checkpoint one, Rinku. Cleared on schedule."], "phase3": ["フェーズ3へ移行。ここから先は、景色も任務のうちです。", "Phase three. From here, the view is part of the mission."], "crOn": ["手動でクルーズモードへ。判断を尊重します。", "Manual cruise engaged. I'll trust your judgment."], "crOff": ["クルーズ解除。地上の速度に戻ります。", "Cruise released. Back to ground speed."], "late5": ["予定より5分遅れ。まだ取り返せる範囲です。", "Five minutes behind. Still recoverable."], "reroute": ["ルート変更を承認。賢明な判断です、エージェント。", "Reroute approved. A wise call, Agent."], "idle1": ["周囲に異常なし。退屈なのは、良い知らせです。", "Perimeter quiet. Boring is good news."], "idle2": ["燃料、電池、集中力。三つとも良好です。", "Fuel, battery, focus. All three nominal."], "idle3": ["通信良好。衛星も一緒に道を見ています。", "Signal strong. The satellites are watching the road with you."], "track": ["次のトラックへ。作戦にはリズムが必要です。", "Next track. Every operation needs a rhythm."], "lyrics": ["歌詞を表示します。歌うのは自由です、前を見ている限りは。", "Lyrics on screen. Singing is permitted, as long as your eyes stay on the road."], "kixNear": ["目標接近。お客様の忘れ物チェックを推奨します。", "Target approaching. Recommend a lost-item check for our guests."], "dropDone": ["任務の半分が完了。帰還ルートを設定します。", "Half the mission complete. Plotting the return route."], "engage": ["ミッション開始。目標をロック。安全運転で、エージェント。", "Mission engaged. Target locked. Drive safely, Agent."], "incoming": ["通信を受信。暗号を解読します。", "Incoming transmission. Decrypting now."], "verified": ["本人確認。ミッションを実行します。", "Identity verified. Executing mission."], "arrive": ["目標地点に到着。ミッション完了。お見事です。", "Target reached. Mission complete. Excellent work."], "link": ["リモート接続を確立。ミッション画面、オンライン。", "Remote link established. Mission display online."], "cruiseAuto": ["スカイゲートブリッジ。クルーズモード、自動で起動。", "Sky Gate Bridge. Cruise mode engaged automatically."], "eta": ["残りの距離と到着時刻は、画面に出ています。", "Distance and arrival time are on your screen."], "leg": ["区間完了。次の合図を待っています。", "Leg complete. Standing by for your signal."], "cpGen": ["チェックポイント通過。予定どおりです。", "Checkpoint cleared. Right on schedule."], "standby": ["待機中。次のミッションをお待ちしています。", "Standing by. Awaiting your next mission."], "engage-2": ["エンジン良好、ルート確定。さらっと決めましょう。", "Engine warm, route locked. Let's make this look effortless."], "engage-3": ["ミッション開始。ミラー確認済み、コーヒーは任意です。", "Mission is live. Mirrors checked. Coffee optional."], "engage-4": ["出発です。目的地は逃げません。こちらも慌てません。", "We're rolling. The destination won't run away, and neither will we rush."], "incoming-2": ["新しい指令が届きました。誰かが、あなたを必要としています。", "New orders just arrived. Someone out there needs you."], "incoming-3": ["通信を受信。詳細を解読しています。", "Transmission received. Unscrambling the details."], "verified-2": ["エージェントを確認。ミッションの鍵をお渡しします。", "Agent confirmed. The mission is yours."], "verified-3": ["指紋一致。いつもどおり、頼りにしています。", "Fingerprint match. Counting on you, as always."], "arrive-2": ["目的地に到着。いつもどおり、教科書どおりです。", "Destination reached. Textbook, as usual."], "arrive-3": ["到着しました。今回の記録は、なめらか、にしておきます。", "We have arrived. I'm filing this one under smooth."], "arrive-4": ["任務完了。ハンドルを置いて、深呼吸をどうぞ。", "Mission complete. Hands off the wheel, and take a deep breath."], "rtb-2": ["帰還します。Crane Nest のお湯は、勝手には沸きません。", "Heading home. The kettle at Crane Nest won't boil itself."], "rtb-3": ["基地へ針路設定。のんびりいきましょう、エージェント。", "Course set for base. Easy pace, Agent."], "obj-2": ["ゲストを無事お届け。ドラマなし。私の好きなやつです。", "Guests delivered with zero drama. My favorite kind."], "obj-3": ["お届け完了。良い旅を、と心の中で手を振っておきます。", "Delivery complete. I'm waving goodbye, on the inside."], "leg-2": ["区間終了。準備ができたら合図をください。", "Segment done. Ready when you are."], "cpGen-2": ["チェックポイント通過。まだ余裕があります。", "Checkpoint passed. Still ahead of the game."], "cpGen-3": ["チェックポイント通過。順調そのものです。", "Checkpoint cleared. Everything is going to plan."], "standby-2": ["回線は静かです。ここで待っています。", "Quiet on the channel. I'll be right here."], "standby-3": ["待機モード。呼んでくれれば、すぐに起きます。", "Standby mode. Call me, and I'm awake."], "area-2": ["目標エリアに入りました。あと少しです。", "Entering the target area. Almost there."], "bags-2": ["荷物を確認。トランクは今日も、黙って働いてくれます。", "Bags confirmed. The trunk, as always, works in silence."], "late5-2": ["少し遅れています。焦らず、でも寄り道はなしで。", "Running a little behind. No panic, but no detours either."], "reroute-2": ["新しいルートを承認。道は一本じゃありません。", "New route approved. There's always more than one road."], "crOn-2": ["クルーズモード。肩の力を抜いていきましょう。", "Cruise mode. Let's relax those shoulders."], "crOff-2": ["クルーズ終了。ここからは、また手作業です。", "Cruise off. Back to the handcrafted part."], "dropDone-2": ["送り届けました。帰りは、私たちだけの時間です。", "Drop off complete. The ride home is all ours."], "idle4": ["路面状況、良好。姿勢は、ちょっとだけ要改善です。", "Road conditions nominal. Your posture, slightly less so."], "idle5": ["補足です。水分補給も、任務のうちです。", "Reminder. Staying hydrated is part of the mission."], "idle6": ["全システム正常。二回確認して、念のため、もう一回。", "All systems green. I checked twice, then once more for style."], "idle7": ["誰かに聞かれたら、これはとても真面目な作戦です。", "If anyone asks, this is a very serious operation."], "idle8": ["前方の交通は友好的です。今のところは。", "Traffic ahead looks friendly. For now."], "idle9": ["この曲、いいですね。私は踊れませんが、気持ちは踊っています。", "Nice track. I can't dance, but I'm dancing on the inside."], "idleM": ["おはようございます、エージェント。朝もルートも新鮮です。", "Good morning, Agent. The day is fresh, and so is the route."], "idleM-2": ["朝の光、良好。眠気がまだ残っていたら、窓を少し開けましょう。", "Morning light looks good. If you're still sleepy, crack a window."], "idleN": ["夜間走行。ライト点灯、目は鋭く、手は穏やかに。", "Night run. Headlights on, eyes sharp, hands calm."], "idleN-2": ["街の灯りが張り切っています。それでも、前に集中を。", "The city lights are showing off. Stay focused anyway."], "goStart": ["フリーミッション開始。目的地を設定。何があるか、見に行きましょう。", "Free mission engaged. Destination set. Let's go see what's out there."], "goStart-2": ["自由行動を承認。行き先はあなたが決めました。道案内は私が。", "Free run approved. You picked the place. I'll handle the directions."], "backStart": ["帰還ルートを設定。次の停車地は、Crane Nest です。", "Return route set. Next stop, Crane Nest."], "backStart-2": ["お疲れさまでした。さあ、基地へ帰りましょう。", "Good work out there. Let's head back to base."], "abStart": ["地点間ミッション。出発地も到着地も、ロックしました。", "Point to point mission. Start and finish, both locked."], "abStart-2": ["新しい区間を設定。ここから、あそこまで。シンプルが一番です。", "New route plotted. From here to there. Simple is best."]};

