/* ---- 02_sfx.js ---- */
let AC=null,M=null,REV=null,DLY=null;
function ac(){try{if(!AC){AC=new (window.AudioContext||window.webkitAudioContext)();
 const comp=AC.createDynamicsCompressor();comp.threshold.value=-16;comp.knee.value=12;comp.ratio.value=5;comp.attack.value=.003;comp.release.value=.2;comp.connect(AC.destination);
 M=AC.createGain();M.gain.value=.9;M.connect(comp);
 const n=Math.floor(AC.sampleRate*2.6),ir=AC.createBuffer(2,n,AC.sampleRate);for(let c=0;c<2;c++){const x=ir.getChannelData(c);for(let i=0;i<n;i++)x[i]=(Math.random()*2-1)*Math.pow(1-i/n,3.4)}
 const cv=AC.createConvolver();cv.buffer=ir;REV=AC.createGain();REV.gain.value=.55;const rl=AC.createBiquadFilter();rl.type="lowpass";rl.frequency.value=6000;REV.connect(rl);rl.connect(cv);cv.connect(M);
 const dl=AC.createDelay(1);dl.delayTime.value=.27;const fb=AC.createGain();fb.gain.value=.34;const dlp=AC.createBiquadFilter();dlp.frequency.value=2800;DLY=AC.createGain();DLY.gain.value=.5;DLY.connect(dl);dl.connect(dlp);dlp.connect(fb);fb.connect(dl);dlp.connect(M)}
 AC.resume();return AC}catch{return null}}
function route(node,o={}){let n=node;if(o.pan&&AC.createStereoPanner){const p=AC.createStereoPanner();p.pan.value=o.pan;n.connect(p);n=p}n.connect(M);if(o.rev){const g=AC.createGain();g.gain.value=o.rev;n.connect(g);g.connect(REV)}if(o.dly){const g=AC.createGain();g.gain.value=o.dly;n.connect(g);g.connect(DLY)}}
function env(g,t,a,d,v){g.gain.setValueAtTime(1e-4,t);g.gain.linearRampToValueAtTime(v,t+a);g.gain.exponentialRampToValueAtTime(1e-4,t+a+d)}
function osc(type,f,t,d,v,o={}){const c=ac();if(!c)return;const T=c.currentTime+t,x=c.createOscillator(),g=c.createGain();x.type=type;x.frequency.setValueAtTime(f,T);if(o.to)x.frequency.exponentialRampToValueAtTime(o.to,T+(o.gl||d));if(o.dt)x.detune.value=o.dt;
 let src=x;if(o.lp){const fl=c.createBiquadFilter();fl.type=o.ft||"lowpass";fl.Q.value=o.q||1;fl.frequency.setValueAtTime(o.lp,T);if(o.lpTo)fl.frequency.exponentialRampToValueAtTime(o.lpTo,T+(o.lpT||d));if(o.lpBack)fl.frequency.exponentialRampToValueAtTime(o.lpBack,T+d+(o.a||.005));src.connect(fl);src=fl}
 src.connect(g);env(g,T,o.a||.005,d,v);route(g,o);x.start(T);x.stop(T+(o.a||.005)+d+.1)}
let NB=null;function nbuf(){if(!NB){const n=AC.sampleRate*3;NB=AC.createBuffer(1,n,AC.sampleRate);const x=NB.getChannelData(0);for(let i=0;i<n;i++)x[i]=Math.random()*2-1}return NB}
function nz(t,d,v,o={}){const c=ac();if(!c)return;const T=c.currentTime+t,s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=nbuf();f.type=o.ft||"bandpass";f.Q.value=o.q||1;f.frequency.setValueAtTime(o.f||3000,T);if(o.to)f.frequency.exponentialRampToValueAtTime(o.to,T+(o.a||.005)+d);
 s.connect(f);f.connect(g);env(g,T,o.a||.003,d,v);route(g,o);s.start(T,Math.random()*1.5);s.stop(T+(o.a||.003)+d+.1)}
function fm(fc,ratio,idx,t,d,v,o={}){const c=ac();if(!c)return;const T=c.currentTime+t,car=c.createOscillator(),mod=c.createOscillator(),mg=c.createGain(),g=c.createGain();
 car.frequency.value=fc;mod.frequency.value=fc*ratio;mg.gain.setValueAtTime(idx,T);mg.gain.exponentialRampToValueAtTime(Math.max(1,idx*.02),T+d*.7);mod.connect(mg);mg.connect(car.frequency);car.connect(g);env(g,T,o.a||.002,d,v);route(g,o);car.start(T);mod.start(T);car.stop(T+d+.1);mod.stop(T+d+.1)}
const SFX={
 tap(){nz(0,.012,.35,{ft:"highpass",f:6000});osc("sine",2600,0,.035,.045,{to:1900})},
 confirm(){osc("sine",90,0,.22,.35,{to:48});fm(1318.5,3.01,500,0,.7,.07,{rev:.5,pan:-.2});fm(1975.5,3.01,300,.07,.9,.05,{rev:.6,dly:.25,pan:.2})},
 lock(){nz(0,.035,.6,{f:2600,q:3});nz(.01,.06,.25,{ft:"highpass",f:7000});osc("sine",62,0,.45,.55,{to:38});
  fm(2637,1.5,900,.02,1.3,.06,{rev:.8,dly:.35});osc("sawtooth",110,.02,1.6,.05,{dt:-8,lp:300,lpTo:2400,lpT:.5,rev:.5});osc("sawtooth",110,.02,1.6,.05,{dt:9,lp:300,lpTo:2400,lpT:.5,rev:.5})},
 engage(){ // 出発: 低い「ブワーン」+ 衝撃
  nz(0,.7,.12,{f:400,to:5000,q:2.5,a:.6,rev:.3});
  const t=.65;osc("sine",55,t,1.8,.7,{to:32,gl:1.2});nz(t,.9,.35,{ft:"lowpass",f:900,to:120});nz(t,.05,.3,{ft:"highpass",f:4000});
  [55,82.4,110,164.8].forEach((f,i)=>{osc("sawtooth",f,t,2.6,.05,{dt:i%2?7:-7,lp:180,lpTo:1600,lpT:.25,lpBack:200,rev:.6})});
  fm(3520,1.41,600,t+.05,1.6,.03,{rev:.9,dly:.4})},
 checkpoint(){fm(1760,2,380,0,.9,.07,{dly:.45,rev:.45,pan:-.35});fm(2637,2,260,.085,1.1,.055,{dly:.45,rev:.5,pan:.35});osc("sine",80,0,.18,.2,{to:50})},
 phase(){for(let i=0;i<6;i++)fm(2400+(i%3)*420,1.5,200,i*.032,.05,.028,{pan:(i%2?.4:-.4)});nz(0,.25,.05,{f:5000,to:1500,q:4,rev:.3})},
 warn(){for(let i=0;i<3;i++){const t=i*.62;osc("sawtooth",740,t,.24,.07,{lp:1800,q:2});osc("sawtooth",554,t+.28,.24,.07,{lp:1800,q:2});osc("sine",70,t,.22,.3)}nz(0,.9,.04,{f:900,q:6,rev:.4})},
 cruiseOn(){ // タービンが回り上がる → 衝撃 → きらめき
  nz(0,1.25,.16,{f:300,to:7000,q:2.2,a:1.15,rev:.35});
  osc("sawtooth",70,0,1.3,.08,{to:640,gl:1.25,lp:500,ft:"bandpass",q:7,lpTo:4000,lpT:1.25,a:1.1});
  osc("square",35,0,1.3,.04,{to:320,gl:1.25,lp:400,lpTo:2000,a:1.1});
  const t=1.25;osc("sine",48,t,2.2,.75,{to:30,gl:1.6});nz(t,1.2,.4,{ft:"lowpass",f:1400,to:100});nz(t,.06,.35,{ft:"highpass",f:5000});
  [73.4,110,146.8,220].forEach((f,i)=>osc("sawtooth",f,t,3.2,.045,{dt:i%2?8:-8,lp:250,lpTo:2600,lpT:.3,lpBack:350,rev:.7}));
  [2637,3520,4186].forEach((f,i)=>fm(f,1.41,500,t+.08+i*.09,1.8,.025,{rev:.9,dly:.5,pan:[-.5,0,.5][i]}))},
 cruiseOff(){osc("sawtooth",560,0,1.1,.07,{to:55,gl:1,lp:3000,ft:"bandpass",q:6,lpTo:300,lpT:1});nz(0,1,.1,{f:6000,to:300,q:2,rev:.3});osc("sine",70,.95,.5,.4,{to:40});fm(880,2,200,.95,.8,.04,{rev:.6})},
 arrive(){this.engage();[110,164.8,246.9,277.2,329.6].forEach((f,i)=>osc("sawtooth",f,.7,4.2,.03,{dt:i%2?6:-6,lp:300,lpTo:2200,lpT:1.6,lpBack:500,rev:.8}));
  [1318.5,1760,2217.5].forEach((f,i)=>fm(f,3.01,300,1.2+i*.16,1.6,.04,{rev:.8,dly:.4,pan:[-.4,0,.4][i]}))},
 stamp(){osc("sine",55,0,.5,.7,{to:35});nz(0,.25,.5,{ft:"lowpass",f:500});nz(0,.03,.4,{f:2200,q:2});fm(1760,1.5,300,.02,.8,.03,{rev:.6})},
};
/* 指紋スキャン中の音 (押している間だけ) */
let scanN=null;function scanStart(){const c=ac();if(!c)return;const T=c.currentTime,s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain(),o=c.createOscillator(),of=c.createBiquadFilter(),og=c.createGain();
 s.buffer=nbuf();s.loop=true;f.type="bandpass";f.Q.value=8;f.frequency.setValueAtTime(600,T);f.frequency.exponentialRampToValueAtTime(5200,T+1.3);g.gain.setValueAtTime(1e-4,T);g.gain.linearRampToValueAtTime(.18,T+.2);
 o.type="sawtooth";o.frequency.setValueAtTime(90,T);o.frequency.exponentialRampToValueAtTime(260,T+1.3);of.type="lowpass";of.Q.value=10;of.frequency.setValueAtTime(200,T);of.frequency.exponentialRampToValueAtTime(3000,T+1.3);og.gain.setValueAtTime(1e-4,T);og.gain.linearRampToValueAtTime(.05,T+.3);
 s.connect(f);f.connect(g);route(g,{rev:.2});o.connect(of);of.connect(og);route(og,{});s.start();o.start();
 const tk=setInterval(()=>fm(3000+Math.random()*1500,1.5,150,0,.03,.02,{pan:Math.random()-.5}),85);
 scanN={stop(){clearInterval(tk);const t=AC.currentTime;g.gain.cancelScheduledValues(t);og.gain.cancelScheduledValues(t);g.gain.setTargetAtTime(1e-4,t,.04);og.gain.setTargetAtTime(1e-4,t,.04);s.stop(t+.3);o.stop(t+.3)}}}
function scanStop(){scanN&&scanN.stop();scanN=null}
/* ===== スパイ映画風の効果音 (オリジナル。既存の曲のメロディーは使わない) =====
   導火線のパチパチ / 金管の「ジャン!」 / 太鼓 / 時計の針 / 緊張の刻み (7 拍子) / 燃えて消える音 */
const SPY={
 fuse(sec=1.8){const c=ac();if(!c)return{stop(){}};const T=c.currentTime;
  const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=nbuf();s.loop=true;f.type="bandpass";f.frequency.value=5200;f.Q.value=1.2;
  g.gain.setValueAtTime(1e-4,T);g.gain.linearRampToValueAtTime(.09,T+.15);s.connect(f);f.connect(g);route(g,{rev:.15});s.start();
  let on=true;const crack=()=>{if(!on)return;nz(0,.004+Math.random()*.012,.25+Math.random()*.45,{ft:"highpass",f:2500+Math.random()*4000,pan:Math.random()*1.2-.6});setTimeout(crack,8+Math.random()*38)};crack();
  const st={stop(){if(!on)return;on=false;const t=c.currentTime;g.gain.cancelScheduledValues(t);g.gain.setTargetAtTime(1e-4,t,.05);s.stop(t+.4)}};setTimeout(()=>st.stop(),sec*1000);return st},
 taiko(t=0,v=.8){osc("sine",62,t,.55,v,{to:36,gl:.4});nz(t,.18,.35*v,{ft:"lowpass",f:420});nz(t,.02,.2*v,{f:1800,q:1})},
 tick(t=0,v=.12){nz(t,.012,v,{ft:"highpass",f:6500});fm(3200,2.1,300,t,.03,v*.25)},
 stab(t=0,root=73.4,v=1){const ch=[1,1.498,2,2.378,3];ch.forEach((m,i)=>{[-9,9].forEach(dt=>osc("sawtooth",root*m,t,.55,.045*v,{dt,lp:500,lpTo:3800,lpT:.05,lpBack:420,a:.012,rev:.45}))});
  osc("sine",root/2,t,.5,.5*v,{to:root/3});nz(t,.06,.18*v,{ft:"highpass",f:3000})},
 strings(t,f,d=.12,v=.05){[-6,6].forEach(dt=>osc("sawtooth",f,t,d,v,{dt,lp:1200,a:.004}))},
 /** 緊張の刻み: 7 拍子 (3+2+2) の太鼓と刻む弦。bars 小節 */
 tension(bars=2,bpm=150){const b=60/bpm/2;const pat=[1,0,0,1,0,1,0];const notes=[73.4,73.4,77.8,73.4,87.3,73.4,77.8];
  for(let k=0;k<bars;k++)for(let i=0;i<7;i++){const t=(k*7+i)*b;if(pat[i])SPY.taiko(t,.55);SPY.tick(t+b*.5,.07);SPY.strings(t,notes[i]*2,b*.7,.035);if(i===0)SPY.strings(t,notes[i]*4,b*1.8,.02)}
  return 14*b*bars/2},
 riser(d=1.1){nz(0,d,.2,{f:300,to:8000,q:2,a:d*.95,rev:.3});osc("sawtooth",80,0,d,.06,{to:900,gl:d,lp:600,lpTo:5000,lpT:d,a:d*.9});
  /* 逆回転のシンバル */const c=ac();const T=c.currentTime,s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=nbuf();f.type="highpass";f.frequency.value=5000;g.gain.setValueAtTime(1e-4,T);g.gain.exponentialRampToValueAtTime(.35,T+d);g.gain.setValueAtTime(1e-4,T+d+.01);s.connect(f);f.connect(g);route(g,{rev:.3});s.start(T);s.stop(T+d+.05)},
 incoming(){SPY.fuse(1.9);[0,.5,1.0,1.5].forEach(t=>fm(1760,2,300,t,.12,.03,{dly:.3}));SPY.taiko(1.9,.9);SPY.stab(1.9,73.4,.9);setTimeout(()=>SPY.tension(2),2300)},
 verify(){fm(2637,1.41,1400,0,.5,.07,{rev:.6});nz(0,.04,.6,{f:2400,q:3});SPY.taiko(0,.7);SPY.stab(.12,98,.7)},
 execute(){SPY.riser(1.1);setTimeout(()=>{SPY.taiko(0,1);SPY.stab(0,73.4,1.15);SPY.stab(.36,77.8,1);SPY.taiko(.36,.8);osc("sine",40,0,2,.7,{to:28})},1100)},
 burn(d=1.3){SPY.fuse(d);nz(0,d,.16,{f:600,to:3200,q:.8,a:d*.8,rev:.4});nz(d*.8,.4,.1,{ft:"lowpass",f:900})},
 checkpoint(){SPY.stab(0,110,.55);fm(2637,2,300,.05,.8,.04,{dly:.45,rev:.5})},
 caution(){for(let i=0;i<3;i++){SPY.stab(i*.55,73.4*(i%2?1.06:1),.75);SPY.taiko(i*.55,.6)}},
 arrive(){SPY.riser(.9);setTimeout(()=>{[0,.3,.6].forEach((t,i)=>{SPY.taiko(t,1);SPY.stab(t,[73.4,82.4,98][i],1)});[110,164.8,220,277.2].forEach((f,i)=>osc("sawtooth",f,.9,4,.03,{dt:i%2?7:-7,lp:300,lpTo:2400,lpT:1.4,lpBack:500,rev:.8}));osc("sine",36,.9,3,.6,{to:30})},900)},
 slam(){SPY.taiko(0,1);nz(0,.05,.5,{f:1800,q:2});osc("sine",48,0,.8,.8,{to:30})},
};

