const DATA=window.KOPS_DATA||{guests:[],devices:[],rooms:[],cabinMissing:true};
const API=window.KOPS_API||{};
const RAD=Math.PI/180,ER=6371000;
const jst=()=>new Date(Date.now()+9*3600e3);
const hm=d=>d.toISOString().slice(11,16);
const pad2=n=>String(n).padStart(2,"0");
const hms=s=>[s/3600|0,(s/60|0)%60,s%60|0].map(pad2).join(":");
const esc=s=>String(s??"").replace(/[<&>"]/g,c=>({"<":"&lt;","&":"&amp;",">":"&gt;",'"':"&quot;"}[c]));
const wait=ms=>new Promise(r=>setTimeout(r,ms));
const dist=(a,b)=>{const x=(b[0]-a[0])*RAD*Math.cos((a[1]+b[1])/2*RAD),y=(b[1]-a[1])*RAD;return Math.hypot(x,y)*ER};/* [lng,lat] */
const LS={get(k,d){try{const v=localStorage.getItem("kops."+k);return v==null?d:JSON.parse(v)}catch{return d}},set(k,v){try{localStorage.setItem("kops."+k,JSON.stringify(v))}catch{}}};
