 function ast(k){const v=CALLV[k];if(!v)return 0;const ms=Math.max(1800,v[1].length*72+700);TALK.until=Date.now()+ms;E.S.sayJ=v[0];E.S.sayE=v[1].toUpperCase();E.ev({t:"say",k:"call/"+k});E.emit("say",{k,j:v[0],e:v[1]});return ms}
