function routeFor(key){const p=ROUTES[key];if(p&&p.length>1)return mkRoute(p);const[pl,dir]=key.split("_");const t=PL[pl]?.ll||HOME,f=PL[pl]?.from?.ll||HOME;return mkRoute(dir==="in"?[t,HOME]:[f,t])}

