/* 検索で選んだ場所 (フリーミッション): 場所とルートを登録する。cp: {key,n,full,ll:[lng,lat],min,pts?:[lng,lat][]} */
function regPlace(cp){if(!cp||!cp.key)return;PL[cp.key]={ja:cp.n,en:cp.en||cp.n,full:cp.full||cp.n,ll:cp.ll,from:cp.from||null,base:{in:cp.min||15,out:cp.min||15}};if(cp.pts&&cp.pts.length>1){ROUTES[cp.key+"_out"]=cp.pts;ROUTES[cp.key+"_in"]=cp.pts.slice().reverse()}}
