 const subs=[];const on=f=>subs.push(f);const off=f=>{const i=subs.indexOf(f);if(i>=0)subs.splice(i,1)};const emit=(t,a)=>subs.forEach(f=>{try{f(t,a)}catch(e){console.error(e)}});
 let R=null,loop=0,vt=0,samples=0,keptN=0,sumS=0,warned=false,lastSay=0,spdSaid={},near1=false,brSaid=false,stopT=0,stopSaid=0,offT=0,offSaid=0,offR=0,rrAt=0,rrBusy=false,rrSaid=0,fltSaid="",wxAt=0,wxRain=null,lastIdle=Date.now(),gpsSrc=null,lastGpsT=0,cabT=null,started=0,firstLy=false;
 /* 声: 字幕 + 音を鳴らす端末 (スマホ or この端末) へ */
 /* 同じ場面でも毎回ちがうセリフ: key, key-2, key-3 … からランダム (直前と同じものは避ける) */
 const lastV={};function pick(k){const P=[k];for(let i=2;VOICE[k+"-"+i];i++)P.push(k+"-"+i);if(P.length<2)return k;const c=P.filter(x=>x!==lastV[k]);const r=c[Math.random()*c.length|0];lastV[k]=r;return r}
 function idleKey(){const h=jst().getUTCHours();const P=["idle1","idle2","idle3","idle4","idle5","idle6","idle7","idle8"];if(S.song)P.push("idle9");if(h>=5&&h<10)P.push("idleM","idleM");if(h>=19||h<4)P.push("idleN","idleN");
  let k;do{k=P[Math.random()*P.length|0]}while(k===lastV.idle&&P.length>1);lastV.idle=k;return k}
