  const m0=S.mis;setTimeout(()=>say(S.leg===0?(m0.kind==="ab"?"abStart":m0.kind==="back"&&m0.cplace?"backStart":m0.kind==="go"&&m0.cplace?"goStart":"engage"):S.mis.legs[S.leg].home?"rtb":"engage",true),900);
